const item = $input.first().json;

const missing = [];
if (!item.workflowName) missing.push('workflowName');
if (!item.aiTaskType) missing.push('aiTaskType');
if (!item.originalInput) missing.push('originalInput');
if (!item.aiOutput) missing.push('aiOutput');
if (!item.notifyEmail) missing.push('notifyEmail');

if (missing.length > 0) {
  return [{
    json: {
      error: true,
      message: 'Missing required fields: ' + missing.join(', '),
      passed: true,
      needsHumanReview: false,
      confidenceScore: 0,
      overallAssessment: 'ERROR',
      originalAiOutput: item.aiOutput || ''
    }
  }];
}

const originalInput = typeof item.originalInput === 'string' ? item.originalInput : JSON.stringify(item.originalInput);
const aiOutput = typeof item.aiOutput === 'string' ? item.aiOutput : JSON.stringify(item.aiOutput);

return [{
  json: {
    error: false,
    workflowName: item.workflowName,
    aiTaskType: item.aiTaskType.toUpperCase(),
    originalInput: originalInput,
    aiOutput: aiOutput,
    aiModel: item.aiModel || 'unknown',
    aiPromptUsed: item.aiPromptUsed || '',
    domainContext: item.domainContext || 'general',
    strictnessThreshold: item.strictnessThreshold != null ? parseInt(item.strictnessThreshold) : 80,
    notifyEmail: item.notifyEmail,
    customValidationInstructions: item.customValidationInstructions || ''
  }
}];

const ctx = $input.first().json;

var baseInstructions = 'You are a validation auditor for a disability law firm. Your job is to audit AI-generated outputs for accuracy, hallucinations, and compliance risks.\n\n' +
  'DOMAIN CONTEXT: ' + ctx.domainContext + '\n' +
  'AI MODEL USED: ' + ctx.aiModel + '\n' +
  (ctx.aiPromptUsed ? 'PROMPT USED: ' + ctx.aiPromptUsed + '\n' : '') +
  '\nORIGINAL INPUT PROVIDED TO THE AI:\n---\n' + ctx.originalInput + '\n---\n\n' +
  'AI OUTPUT BEING VALIDATED:\n---\n' + ctx.aiOutput + '\n---\n';

var jsonFormat = '\n\nRespond with ONLY a valid JSON object (no code fences, no markdown, no extra text):\n' +
  '{\n' +
  '  "confidenceScore": <integer 0-100>,\n' +
  '  "overallAssessment": "<PASS|REVIEW_NEEDED|FAIL>",\n' +
  '  "flaggedIssues": [\n' +
  '    { "issue": "<description>", "severity": "<HIGH|MEDIUM|LOW>", "recommendation": "<what to do>" }\n' +
  '  ],\n' +
  '  "sourceCitations": [\n' +
  '    { "claim": "<what the AI claimed>", "source": "<exact text from input or NOT SOURCED>", "status": "<VERIFIED|PLAUSIBLE|UNSOURCED>" }\n' +
  '  ],\n' +
  '  "reasoning": "<summary of validation findings>"\n' +
  '}';

var prompt = '';

if (ctx.aiTaskType === 'EVALUATION') {
  prompt = baseInstructions +
    '\nTASK: EVALUATION VALIDATION\n' +
    'The AI was asked to evaluate/classify the original input. For each criterion the AI evaluated:\n' +
    '1. Cite the EXACT text from the original input that supports or contradicts the AI conclusion\n' +
    '2. Check for FALSE POSITIVES - the AI flagged something not actually present\n' +
    '3. Check for FALSE NEGATIVES - the AI missed something it should have caught\n' +
    '4. Rate whether evidence STRONGLY, MODERATELY, or WEAKLY supports each conclusion\n' +
    (ctx.customValidationInstructions ? '\nADDITIONAL VALIDATION RULES:\n' + ctx.customValidationInstructions + '\n' : '') +
    jsonFormat;
} else if (ctx.aiTaskType === 'GENERATION') {
  prompt = baseInstructions +
    '\nTASK: GENERATION VALIDATION\n' +
    'The AI generated content based on the original input. For EVERY factual claim in the generated content:\n' +
    '1. Cite WHERE that fact comes from in the original input\n' +
    '2. If no source exists, label it NOT SOURCED - ASSUMED BY AI\n' +
    '3. Label each claim: VERIFIED (traceable to input), PLAUSIBLE (reasonable but not directly sourced), or UNSOURCED (no basis in input - potential hallucination)\n\n' +
    'Pay special attention to:\n' +
    '- Hallucinated legal claims, statistics, names, dates, and procedures\n' +
    '- Claims about SSDI, disability benefits, or legal processes not in the source material\n' +
    '- Invented attorney names, case numbers, or office locations\n' +
    (ctx.customValidationInstructions ? '\nADDITIONAL VALIDATION RULES:\n' + ctx.customValidationInstructions + '\n' : '') +
    jsonFormat;
} else if (ctx.aiTaskType === 'CUSTOM') {
  prompt = baseInstructions +
    '\nTASK: CUSTOM VALIDATION\n' +
    'Validate the AI output using the following custom criteria:\n\n' +
    (ctx.customValidationInstructions || 'No custom instructions provided. Perform a general accuracy and hallucination check.') +
    jsonFormat;
} else {
  prompt = baseInstructions +
    '\nTASK: GENERAL VALIDATION\n' +
    'Perform a general accuracy and hallucination check on the AI output.\n' +
    jsonFormat;
}

return [{
  json: {
    workflowName: ctx.workflowName,
    aiTaskType: ctx.aiTaskType,
    originalInput: ctx.originalInput,
    aiOutput: ctx.aiOutput,
    aiModel: ctx.aiModel,
    aiPromptUsed: ctx.aiPromptUsed,
    domainContext: ctx.domainContext,
    strictnessThreshold: ctx.strictnessThreshold,
    notifyEmail: ctx.notifyEmail,
    customValidationInstructions: ctx.customValidationInstructions,
    validationPrompt: prompt
  }
}];

const item = $input.first();
const context = $('Build Validation Prompt1').first().json;
let text = item.json.output || '';

// Strip code fences if present
text = text.replace(/```json\s*/g, '').replace(/```\s*/g, '').trim();

var parsed;
try {
  parsed = JSON.parse(text);
} catch (e) {
  // Try to find JSON object in the text
  var jsonMatch = text.match(/\{[\s\S]*\}/);
  if (jsonMatch) {
    try {
      parsed = JSON.parse(jsonMatch[0]);
    } catch (e2) {
      parsed = {
        confidenceScore: 50,
        overallAssessment: 'REVIEW_NEEDED',
        flaggedIssues: [{ issue: 'Validation response could not be parsed', severity: 'MEDIUM', recommendation: 'Manual review recommended' }],
        sourceCitations: [],
        reasoning: 'Parse error: ' + e.message
      };
    }
  } else {
    parsed = {
      confidenceScore: 50,
      overallAssessment: 'REVIEW_NEEDED',
      flaggedIssues: [{ issue: 'Validation response could not be parsed', severity: 'MEDIUM', recommendation: 'Manual review recommended' }],
      sourceCitations: [],
      reasoning: 'Parse error: ' + e.message
    };
  }
}

var citations = parsed.sourceCitations || [];

return [{
  json: {
    workflowName: context.workflowName,
    aiTaskType: context.aiTaskType,
    originalInput: context.originalInput,
    aiOutput: context.aiOutput,
    aiModel: context.aiModel,
    domainContext: context.domainContext,
    strictnessThreshold: context.strictnessThreshold,
    notifyEmail: context.notifyEmail,
    confidenceScore: parsed.confidenceScore != null ? parsed.confidenceScore : 50,
    overallAssessment: parsed.overallAssessment || 'REVIEW_NEEDED',
    flaggedIssues: parsed.flaggedIssues || [],
    sourceCitations: citations,
    reasoning: parsed.reasoning || '',
    unsourcedClaimCount: citations.filter(function(c) { return c.status === 'UNSOURCED'; }).length,
    totalClaimsChecked: citations.length
  }
}];

const item = $input.first().json;
var score = item.confidenceScore;
var threshold = item.strictnessThreshold;
var flaggedIssues = item.flaggedIssues || [];
var highSeverityCount = flaggedIssues.filter(function(i) { return i.severity === 'HIGH'; }).length;

var passed = score >= threshold;
var needsHumanReview = !passed;

// Override 1: any HIGH-severity issue forces human review
if (highSeverityCount > 0) {
  needsHumanReview = true;
}

// Override 2: if the AI itself says REVIEW_NEEDED or FAIL, force human review
if (item.overallAssessment === 'REVIEW_NEEDED' || item.overallAssessment === 'FAIL') {
  needsHumanReview = true;
}

var reviewLevel = 'NONE';
if (needsHumanReview) {
  if (score < threshold * 0.5 || highSeverityCount >= 2) {
    reviewLevel = 'CRITICAL';
  } else if (highSeverityCount >= 1 || score < threshold * 0.75) {
    reviewLevel = 'HIGH';
  } else {
    reviewLevel = 'MODERATE';
  }
}

var decisionSummary = (passed && !needsHumanReview)
  ? 'PASSED: Score ' + score + '/' + threshold + ' threshold. No critical issues.'
  : 'FLAGGED: Score ' + score + '/' + threshold + ' threshold. ' + highSeverityCount + ' high-severity issue(s). Review level: ' + reviewLevel + '.';

return [{
  json: {
    workflowName: item.workflowName,
    aiTaskType: item.aiTaskType,
    originalInput: item.originalInput,
    aiOutput: item.aiOutput,
    aiModel: item.aiModel,
    domainContext: item.domainContext,
    strictnessThreshold: item.strictnessThreshold,
    notifyEmail: item.notifyEmail,
    confidenceScore: item.confidenceScore,
    overallAssessment: item.overallAssessment,
    flaggedIssues: item.flaggedIssues,
    sourceCitations: item.sourceCitations,
    reasoning: item.reasoning,
    unsourcedClaimCount: item.unsourcedClaimCount,
    totalClaimsChecked: item.totalClaimsChecked,
    passed: passed,
    needsHumanReview: needsHumanReview,
    reviewLevel: reviewLevel,
    decisionSummary: decisionSummary,
    highSeverityCount: highSeverityCount,
    validationTimestamp: new Date().toISOString()
  }
}];

// Pull from Apply Strictness Threshold - Write Audit Log (Google Sheets) strips
// the data down to 14 flat columns, losing arrays like flaggedIssues and sourceCitations.
const item = $('Apply Strictness Threshold1').first().json;

var n8nBaseUrl = 'https://simpledotbiz.app.n8n.cloud';
var reviewWebhookUrl = n8nBaseUrl + '/webhook/review-response';
var subWorkflowId = '6duP007x1yFIH99y';

var score = item.confidenceScore;
var threshold = item.strictnessThreshold;
var severity = item.reviewLevel;
var workflowName = item.workflowName;
var flaggedIssues = item.flaggedIssues || [];
var citations = (item.sourceCitations || []).slice(0, 10);
var executionId = $execution.id || 'N/A';
var executionLink = n8nBaseUrl + '/workflow/' + subWorkflowId + '/executions/' + executionId;

var issuesHtml = '';
for (var i = 0; i < flaggedIssues.length; i++) {
  var issue = flaggedIssues[i];
  var color = issue.severity === 'HIGH' ? '#dc3545' : (issue.severity === 'MEDIUM' ? '#ffc107' : '#28a745');
  issuesHtml += '<tr>' +
    '<td style="padding:8px;border:1px solid #ddd;">' + (i + 1) + '</td>' +
    '<td style="padding:8px;border:1px solid #ddd;"><span style="color:' + color + ';font-weight:bold;">' + issue.severity + '</span></td>' +
    '<td style="padding:8px;border:1px solid #ddd;">' + issue.issue + '</td>' +
    '<td style="padding:8px;border:1px solid #ddd;">' + issue.recommendation + '</td>' +
    '</tr>';
}

var citationsHtml = '';
for (var j = 0; j < citations.length; j++) {
  var c = citations[j];
  var statusColor = c.status === 'VERIFIED' ? '#28a745' : (c.status === 'PLAUSIBLE' ? '#ffc107' : '#dc3545');
  citationsHtml += '<tr>' +
    '<td style="padding:8px;border:1px solid #ddd;">' + c.claim + '</td>' +
    '<td style="padding:8px;border:1px solid #ddd;">' + c.source + '</td>' +
    '<td style="padding:8px;border:1px solid #ddd;"><span style="color:' + statusColor + ';font-weight:bold;">' + c.status + '</span></td>' +
    '</tr>';
}

var severityColor = severity === 'CRITICAL' ? '#dc3545' : (severity === 'HIGH' ? '#ff6b35' : '#ffc107');

// Single review button
var actionButtonsHtml = '<div style="padding:16px;background:#f0f4ff;border:1px solid #ddd;border-top:none;text-align:center;">' +
  '<a href="' + reviewWebhookUrl + '?executionId=' + encodeURIComponent(executionId) + '" ' +
  'style="display:inline-block;padding:12px 32px;background:#1a73e8;color:white;text-decoration:none;border-radius:4px;font-weight:bold;font-size:16px;">Review Now</a>' +
  '</div>';

var emailBody = '<div style="font-family:Arial,sans-serif;max-width:800px;margin:0 auto;">' +
  '<div style="background:' + severityColor + ';color:white;padding:16px;border-radius:8px 8px 0 0;">' +
  '<h2 style="margin:0;">AI Validation Review Required</h2>' +
  '<p style="margin:4px 0 0;">Workflow: ' + workflowName + ' | Severity: ' + severity + '</p>' +
  '</div>' +
  actionButtonsHtml +
  '<div style="padding:16px;border:1px solid #ddd;border-top:none;">' +
  '<table style="width:100%;border-collapse:collapse;margin-bottom:16px;">' +
  '<tr><td style="padding:8px;font-weight:bold;">Confidence Score:</td><td style="padding:8px;">' + score + ' / ' + threshold + ' threshold</td></tr>' +
  '<tr><td style="padding:8px;font-weight:bold;">Assessment:</td><td style="padding:8px;">' + item.overallAssessment + '</td></tr>' +
  '<tr><td style="padding:8px;font-weight:bold;">Task Type:</td><td style="padding:8px;">' + item.aiTaskType + '</td></tr>' +
  '<tr><td style="padding:8px;font-weight:bold;">AI Model:</td><td style="padding:8px;">' + item.aiModel + '</td></tr>' +
  '<tr><td style="padding:8px;font-weight:bold;">Execution ID:</td><td style="padding:8px;">' + executionId + '</td></tr>' +
  '</table>' +
  '<h3>Reasoning</h3>' +
  '<p>' + item.reasoning + '</p>' +
  (flaggedIssues.length > 0 ?
    '<h3>Flagged Issues (' + flaggedIssues.length + ')</h3>' +
    '<table style="width:100%;border-collapse:collapse;">' +
    '<tr style="background:#f5f5f5;"><th style="padding:8px;border:1px solid #ddd;">#</th><th style="padding:8px;border:1px solid #ddd;">Severity</th><th style="padding:8px;border:1px solid #ddd;">Issue</th><th style="padding:8px;border:1px solid #ddd;">Recommendation</th></tr>' +
    issuesHtml +
    '</table>' : '') +
  (citations.length > 0 ?
    '<h3>Source Citations (showing ' + citations.length + ')</h3>' +
    '<table style="width:100%;border-collapse:collapse;">' +
    '<tr style="background:#f5f5f5;"><th style="padding:8px;border:1px solid #ddd;">Claim</th><th style="padding:8px;border:1px solid #ddd;">Source</th><th style="padding:8px;border:1px solid #ddd;">Status</th></tr>' +
    citationsHtml +
    '</table>' : '') +
  '<h3>Full Execution Details</h3>' +
  '<p>View the complete AI output and validation details in the n8n execution log:</p>' +
  '<a href="' + executionLink + '" style="display:inline-block;padding:10px 20px;background:#1a73e8;color:white;text-decoration:none;border-radius:4px;font-weight:bold;">View Execution Log</a>' +
  '<p style="font-size:12px;color:#666;margin-top:8px;">Accessible only to authorized n8n users.</p>' +
  '</div></div>';

var emailSubject = '[AI REVIEW ' + severity + '] ' + workflowName + ' - Score ' + score + '/' + threshold;

return [{
  json: {
    workflowName: item.workflowName,
    aiTaskType: item.aiTaskType,
    originalInput: item.originalInput,
    aiOutput: item.aiOutput,
    aiModel: item.aiModel,
    domainContext: item.domainContext,
    strictnessThreshold: item.strictnessThreshold,
    notifyEmail: item.notifyEmail,
    confidenceScore: item.confidenceScore,
    overallAssessment: item.overallAssessment,
    flaggedIssues: item.flaggedIssues,
    sourceCitations: item.sourceCitations,
    reasoning: item.reasoning,
    unsourcedClaimCount: item.unsourcedClaimCount,
    totalClaimsChecked: item.totalClaimsChecked,
    passed: item.passed,
    needsHumanReview: item.needsHumanReview,
    reviewLevel: item.reviewLevel,
    decisionSummary: item.decisionSummary,
    highSeverityCount: item.highSeverityCount,
    validationTimestamp: item.validationTimestamp,
    emailBody: emailBody,
    emailSubject: emailSubject,
    executionId: executionId
  }
}];

// Reference Apply Strictness Threshold directly - this has all validation data
// regardless of whether we came via the email branch (TRUE) or skipped it (FALSE).
// The Gmail node output replaces input data with API metadata, so $input is unreliable here.
const item = $('Apply Strictness Threshold1').first().json;

return [{
  json: {
    passed: item.passed,
    needsHumanReview: item.needsHumanReview,
    confidenceScore: item.confidenceScore,
    overallAssessment: item.overallAssessment,
    reviewLevel: item.reviewLevel,
    decisionSummary: item.decisionSummary,
    reasoning: item.reasoning,
    flaggedIssues: item.flaggedIssues,
    sourceCitations: item.sourceCitations,
    unsourcedClaimCount: item.unsourcedClaimCount,
    totalClaimsChecked: item.totalClaimsChecked,
    validationTimestamp: item.validationTimestamp,
    strictnessThreshold: item.strictnessThreshold,
    workflowName: item.workflowName,
    originalAiOutput: item.aiOutput,
    executionId: $execution.id
  }
}];
